components.css:
.ds-button{
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 4px;
  border: none;
  border-radius: 18px;
  cursor: pointer;
  font-size: 14px;
  line-height: 22px;
  color: var(--dsw-alias-label-primary);
  background: transparent;
  padding: 0 14px;
}
.ds-button:disabled{
  cursor: not-allowed;
  opacity: 0.4;
}
.ds-md{
  height: 36px;
}
.ds-sm{
  height: 28px;
  font-size: 12px;
  line-height: 18px;
  padding: 0 10px;
  border-radius: 14px;
}
.ds-primary{
  background: var(--dsw-alias-button-primary-fill);
  color: var(--dsw-alias-label-primary-foreground);
}
.ds-primary:hover:not(:disabled){
  background: var(--dsw-alias-button-primary-hover);
}
.ds-ghost:hover:not(:disabled){
  background: var(--dsw-alias-interactive-bg-hover);
}
.ds-ghost:active:not(:disabled){
  background: var(--dsw-alias-interactive-bg-active);
}
.ds-outline{
  border: 0.5px solid var(--dsw-alias-border-l3);
  background: transparent;
}
.ds-outline:hover:not(:disabled){
  background: var(--dsw-alias-interactive-bg-hover);
}
.ds-toolbar{
  background: var(--dsw-alias-button-tool-bar-fill);
}
.ds-toolbar:hover:not(:disabled){
  background: var(--dsw-alias-button-tool-bar-hover);
}
.ds-icon{
  display: inline-flex;
  width: 16px;
  height: 16px;
  align-items: center;
  justify-content: center;
}

.ds-wrap{
  display: inline-flex;
  align-items: center;
  gap: 6px;
  height: 32px;
  padding: 0 8px;
  border: 0.5px solid var(--dsw-alias-border-l4);
  border-radius: 8px;
  background: var(--dsw-alias-bg-layer-1);
}
.ds-wrap:focus-within{
  border-color: var(--dsw-alias-brand-primary);
}
.ds-icon{
  display: inline-flex;
  width: 16px;
  height: 16px;
  align-items: center;
  justify-content: center;
  color: var(--dsw-alias-label-tertiary);
}
.ds-input{
  flex: 1;
  min-width: 0;
  border: none;
  outline: none;
  background: transparent;
  font-size: 14px;
  line-height: 22px;
  color: var(--dsw-alias-label-primary);
}
.ds-input::placeholder{
  color: var(--dsw-alias-label-dimmed);
}

.ds-row{
  width: 100%;
  display: flex;
  align-items: center;
  gap: 4px;
  height: 28px;
  flex: none;
  padding: 4px;
  border: none;
  border-radius: 6px;
  background: transparent;
  text-align: left;
  cursor: pointer;
}
.ds-row:hover{
  background: var(--dsw-alias-interactive-bg-hover);
}
.ds-rowSelected,
.ds-rowSelected:hover{
  background: var(--dsw-alias-interactive-bg-active, var(--dsw-alias-interactive-bg-hover));
}
.ds-rowName{
  flex: 1 1 0;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 13px;
  line-height: 20px;
  font-weight: 500;
  color: var(--dsw-alias-label-primary);
}

